typedef float rational_t;
typedef float vm_num_t;

struct vector3d
{
  float x;
  float y;
  float z;
};

struct po
{
  char data[72];
};

class game_clock_t
{
  unsigned int start;

public:
  void reset();
  rational_t elapsed() const;
};

class vm_stack
{
  char pad[8];

public:
  char *SP;
  void *thread;
  bool push(const char *, int);
};

class script_library_class
{
public:
  class function
  {
  public:
    typedef int entry_t;
    virtual bool operator()(vm_stack &, entry_t) = 0;
  };
};

enum
{
  FIRST_ENTRY = 0
};

class slf_wait_fps_test_t : public script_library_class::function
{
public:
  struct sdata_t
  {
    game_clock_t clock;
    po initial_cam_po;
    vector3d initial_target;
    rational_t initial_roll;
    vm_num_t avg_fps;
    int num_frames;
    bool disable_marky;
  };

  struct parms_t
  {
    vm_num_t min_fps;
    vm_num_t duration;
    vector3d pos;
    vector3d facing;
  };

  virtual bool operator()(vm_stack &stack, entry_t entry);
};

bool slf_wait_fps_test_t::operator()(vm_stack &stack, entry_t entry)
{
  sdata_t *sdata = (sdata_t *)stack.SP;
  stack.SP -= sizeof(parms_t);
  parms_t *parms = (parms_t *)stack.SP;

  if (entry == FIRST_ENTRY)
  {
    sdata->clock.reset();
    return false;
  }
  else
  {
    if (sdata->clock.elapsed() >= parms->duration)
    {
      vm_num_t result = 1.0f;
      if (!stack.push((const char *)&result, sizeof(result)))
        return true;
      return true;
    }
    else
    {
      return false;
    }
  }
}
